import { rm } from "node:fs/promises";
import { fixturePath } from "./access-fixture";
export default async function cleanup() {
  if (process.env.E2E_BASE_URL) return;
  // Only files generated by this harness, never a developer database/config.
  for (const path of [
    fixturePath,
    ".wrangler/e2e-db-token",
    "dist/server/test-only-d1.mjs",
    "dist/server/test-only-access.mjs",
    "dist/server/test-only-fetch.mjs",
    "dist/server/test-only-wrangler.json",
  ])
    await rm(path, { force: true });
}
